-- Demo seed: Ironworks Roster (GB)
-- Synthetic demo data (fake identities, .invalid contacts, no real sends).
-- Usage: docker exec -i crowdrelay-demo-roster-postgres-1 psql -U crowdrelay -d crowdrelay -v ws_slug=demo-roster -f ops/demo/demo_seed_roster_gb.sql
-- Idempotent: skips when the workspace already has events.
\set ON_ERROR_STOP on
select id as ws_id from workspaces where slug = :'ws_slug' \gset
\if :{?ws_id}
\else
  \echo 'workspace not found for ws_slug'
  \quit 1
\endif
select count(*) > 0 as already_seeded from events where workspace_id = :'ws_id' \gset
\if :already_seeded
  \echo 'workspace already seeded -- skipping'
\else
SET session_replication_role = replica;
